6.9.1 单一外中断的应用
参考程序如下：
#include <reg51.h>
#define uchar unsigned char
//延时函数Delay( )，i形式参数，不能赋初值
void Delay(unsigned int i)
{
unsigned int j;
for(;i > 0;i--)
for(j=0;j<333;j++) // 晶振为 12 MHz ，j 选择与晶振
//频率有关
{;} //空函数
}

6.9.1 单一外中断的应用
void main( ) //主函数
{
EA=1; //总中断允许
EX0=1; //允许外部中断0中断
IT0=1; //选择外部中断0为跳沿触发方式
while(1) //循环
{
P1=0; // P1口的8只LED全亮
}
}

6.9.1 单一外中断的应用
//外中断0的中断服务函数
void int0( ) interrupt {
uchar m;
EX0=0; //禁止外部中断0中断
for(m=0;m<5;m++) //交替闪烁5次
{
P1=0x0f; //低4位LED灭，高4位LED亮
Delay(400) ; //延时
P1=0xf0; //高4位LED灭，低4位LED亮
Delay(400); //延时
EX0=1; //中断返回前，打开外部中断0中断
}

