6.9.2 两个外中断的应用
//外中断0的中断服务函数
void int0_isr(void) interrupt 0 using 1
{
uchar n;
for(n=0;n<10;n++) //高、低4位显示10次
{
P1=0x0f; //低4位LED灭，高4位LED亮
Delay(500); //延时
P1=0xf0; //高4位LED灭，低4位LED亮
Delay(500); //延时
} 
}

6.9.2 两个外中断的应用
//外中断1中断服务函数
void int1_isr (void) interrupt 2 using 2
{
uchar m;
for(m=0;m<10;m++) //闪烁显示10次
{
P1=0xff; //全灭
Delay(500); //延时
P1=0; //全亮
Delay(500); //延时
}
}

